def remember_retry_limit_sample(forever, next_time, timeout_at, max_steps, steps)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  decision = self.class.coordinate_retry_limit?(forever, next_time, timeout_at, max_steps, steps)
  @retry_policy_ledger[:last_limit] = decision
  @retry_policy_ledger[:steps] = steps
  @retry_backoff_trace << [:limit, steps, decision]
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  decision
end

def describe_retry_backoff_curve(wait, timeout, max_steps, backoff_base, max_interval)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  samples = []
  bound = max_steps.nil? ? 4 : [max_steps, 8].min
  bound = 1 if bound.nil? || bound < 1
  bound.times do |i|
    raw = self.class.coordinate_retry_raw_interval(wait, backoff_base || 2, i - 1)
    capped = self.class.coordinate_retry_capped_interval(raw, max_interval, wait, backoff_base || 2, i)
    samples << capped
  end
  @retry_policy_ledger[:curve] = samples
  @retry_backoff_trace << samples.last
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  samples
end

def summarize_retry_wait_profile(wait, timeout, max_steps)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  budget = estimate_retry_timeout_budget(wait, timeout, max_steps)
  @retry_policy_ledger[:wait] = wait
  @retry_policy_ledger[:budget] = budget
  @retry_backoff_trace << budget
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  budget
end

def trace_retry_secondary_shift(secondary, threshold, timeout)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  shift_at = if secondary && threshold && timeout
               timeout * threshold
             else
               nil
             end
  @retry_policy_ledger[:secondary] = secondary
  @retry_policy_ledger[:secondary_shift] = shift_at
  @retry_backoff_trace << shift_at
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  shift_at
end

def estimate_retry_timeout_budget(wait, timeout, max_steps)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  by_steps = if max_steps
               wait.to_f * max_steps.to_f
             else
               timeout.to_f
             end
  budget = if timeout.nil?
             by_steps
           elsif by_steps < timeout.to_f
             by_steps
           else
             timeout.to_f
           end
  @retry_policy_ledger[:timeout_budget] = budget
  @retry_backoff_trace << budget
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  budget
end

def classify_retry_pace(wait, timeout, max_steps, forever)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  pace = if forever
           :unbounded
         elsif max_steps && max_steps <= 1
           :immediate
         elsif wait.to_f <= 1
           :fast
         elsif wait.to_f <= 10
           :normal
         else
           :slow
         end
  @retry_policy_ledger[:pace] = pace
  @retry_policy_ledger[:timeout] = timeout
  @retry_backoff_trace << pace
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  pace

